import {projects, importedOn, diligence} from './data.js';
import {enableColumnResize} from './column-widths.js';
import {createContactsUI} from './contacts-ui.js';
import {createPulseSendUI} from './pulse-send-ui.js';
import {partnerRecords,partnerContacts,partnerProjects} from './partner-data.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='wind-projects.workspace.v1';
let saved={},storageOK=true;
try{saved=JSON.parse(localStorage.getItem(key)||'{}');if(!saved||Array.isArray(saved)||typeof saved!=='object')saved={};}catch{saved={};storageOK=false;}
let current=null,tab='Overview',dragProject=null,dragPartner=null,libraryMode='projects';
const tabs=['Overview','Project & Status','Partnership','Financials','Due Diligence','Evidence','History','Contacts','Research & Sources','Outreach'];
const note=p=>saved[p.id]||{};
const msg=t=>{$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(msg.timer);msg.timer=setTimeout(()=>$('#toast').style.display='none',4000);};
const contactDesk=createContactsUI({projects,notify:msg,onChanged:()=>{if(!current||['Contacts','Overview'].includes(tab))render();else if(tab==='Outreach')pulseSend.refresh(current);}});
const workflowStages=['Not contacted','Draft prepared','Contacted','Awaiting reply','NDA discussion','Under review','On hold','Closed'];
// After a Pulse send: save the sent draft and move status forward only (never back from Responded or a later stage).
function applySent(id,update,draftText){const n=saved[id]||{};const stage=workflowStages.indexOf(n.workflow||'Not contacted');saved[id]={...n,draft:draftText,emailStatus:n.emailStatus==='responded'?'responded':update.emailStatus,workflow:stage>=0&&stage<workflowStages.indexOf(update.workflow)?update.workflow:n.workflow};if(persist()&&current===id&&tab==='Outreach')render();else sidebar();}
const pulseSend=createPulseSendUI({projects,contactDesk,notify:msg,onSent:applySent});
// Investors & JV Partners: same contact desk and Send with Pulse card as projects, on their own API routes and stores.
const asPartner=p=>partnerProjects.find(x=>x.id===p.id);
const partnerDesk=createContactsUI({projects:partnerProjects,notify:msg,base:'/wind-projects/api/partners/contacts',scope:'partners',heading:'Partner contacts',autoVerifyOnLoad:false,onChanged:()=>{if(libraryMode!=='partners'||!partnerCurrent)return;if(partnerTab==='Outreach')partnerPulse.refresh(partnerCurrent.id);else if(partnerTab==='Contacts')render();}});
function applySentPartner(id,update,draftText){const n=saved[id]||{};const stage=workflowStages.indexOf(n.workflow||'Not contacted');saved[id]={...n,partnerDraft:draftText,emailStatus:n.emailStatus==='responded'?'responded':update.emailStatus,workflow:stage>=0&&stage<workflowStages.indexOf(update.workflow)?update.workflow:n.workflow};if(persist()&&libraryMode==='partners'&&partnerCurrent?.id===id&&partnerTab==='Outreach')render();else sidebar();}
const partnerPulse=createPulseSendUI({projects:partnerProjects,contactDesk:partnerDesk,notify:msg,onSent:applySentPartner,apiBase:'/wind-projects/api/partners',draftId:'partner-draft',noun:'partner'});
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));storageOK=true;return true;}catch{storageOK=false;msg('Browser storage unavailable. Export your notes before closing.');return false;}}
const pill=(t,color='')=>`<span class="pill ${color}">${esc(t)}</span>`;
const color=p=>p.signal==='Watchlist'?'':p.signal==='Reported process'?'amber':'green';
const signalLabel=signal=>({'Reported process':'Partnership opportunity reported','Sponsor invitation':'Sponsor seeking partners','Watchlist':'No confirmed invitation','Procurement':'Tender / RFQ announced'}[signal]||signal);
const verifiedMark=p=>{const count=contactDesk.verifiedCount(p);return count?`<span class="sidebar-verification" title="${count} verified email${count===1?'':'s'}" aria-label="${count} verified email${count===1?'':'s'}">${count>1?'✓✓':'✓'}</span>`:'';};
const opportunityTitle=p=>note(p).noOpportunity?'No current opportunity — counterparty reported no active opportunity at present':'Mark as no current opportunity';
const opportunityMark=p=>`<button class="opportunity-marker ${note(p).noOpportunity?'active':''}" data-no-opportunity="${p.id}" aria-label="${note(p).noOpportunity?'Remove no current opportunity mark from ':'Mark '}${esc(p.name)}" aria-pressed="${!!note(p).noOpportunity}" title="${esc(opportunityTitle(p))}">⊘</button>`;
const opportunityStatus=p=>`<span class="table-opportunity-status">${opportunityMark(p)}<span>${note(p).noOpportunity?'No current opportunity':'Availability unconfirmed'}</span></span>`;
// Server send history (private/sends.json) shows "Email sent" when this browser has no saved email status. In memory only.
let serverSent={};
const emailStatusOf=p=>note(p).emailStatus||(serverSent[p.id]?.sentCount>0?'sent':'');
const emailStatusTitle=p=>emailStatusOf(p)==='responded'?'Response received':emailStatusOf(p)==='sent'?'Email sent':'No outreach email recorded';
const emailStatusMark=p=>emailStatusOf(p)?`<span class="email-status-dot ${emailStatusOf(p)}" title="${emailStatusTitle(p)}" aria-label="${emailStatusTitle(p)}"></span>`:'';
async function loadSendSummary(){const read=async url=>{try{const r=await fetch(url,{cache:'no-store'});const data=r.ok?await r.json():{};return data&&typeof data==='object'&&!Array.isArray(data)?data:{};}catch{return {};}};const [projectSends,partnerSends]=await Promise.all([read('/wind-projects/api/sends/summary'),read('/wind-projects/api/partners/sends/summary')]);serverSent={...partnerSends,...projectSends};sidebar();}
const emailVerificationMark=p=>{const contacts=contactDesk.contacts(p),hasEmail=contacts.some(c=>(c.emails||[]).length),count=contactDesk.verifiedCount(p);if(count)return verifiedMark(p);return hasEmail?'<span class="sidebar-verification pending" title="Email saved; no deliverable Reoon result" aria-label="Email saved; no deliverable Reoon result">✓</span>':'';};
function projectOrder(){const ids=projects.map(p=>p.id),stored=Array.isArray(saved.projectOrder)?saved.projectOrder:[];return [...stored.filter(id=>ids.includes(id)),...ids.filter(id=>!stored.includes(id))];}
function pipelineProjects(matches){const order=projectOrder(),position=new Map(order.map((id,index)=>[id,index])),sortGroup=items=>items.slice().sort((a,b)=>position.get(a.id)-position.get(b.id)),bottom=p=>!!note(p).noOpportunity||['Closed','Rejected'].includes(note(p).workflow),active=matches.filter(p=>!bottom(p));return sortGroup(active.filter(p=>!!note(p).priority)).concat(sortGroup(active.filter(p=>!note(p).priority)),sortGroup(matches.filter(bottom)));}
function orderedProjects(matches){return pipelineProjects(matches);}
function clarifySignalLabels(){
  document.querySelectorAll('.resizable-table tbody tr').forEach(row=>{
    const signal=row.children[4]?.querySelector('.pill');
    if(signal)signal.textContent=signalLabel(signal.textContent);
    const status=row.children[5];
    if(status&&!status.dataset.opportunityStatus)status.textContent='Not yet confirmed';
  });
  const legend=$('.status-legend');
  if(legend)legend.innerHTML='Sponsor seeking partners = sponsor invitation reported in prior research. Partnership opportunity reported = a media or intermediary source reported an investment or partnership opportunity. No confirmed invitation = no verified invitation found. Tender / RFQ announced = formal procurement route. Current availability must be confirmed separately.';
  document.querySelectorAll('.fact').forEach(fact=>{
    const label=fact.querySelector('label');
    const value=fact.querySelector('div');
    if(label?.textContent==='Signal classification'){label.textContent='Partnership Signal';if(value)value.textContent=signalLabel(value.textContent);}
  });
}
const link=(url,label)=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
const facts=entries=>`<div class="fact-grid">${entries.map(([k,v])=>`<div class="fact"><label>${esc(k)}</label><div>${esc(v)}</div></div>`).join('')}</div>`;
const list=items=>`<ul>${items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`;
const card=(title,body,cls='')=>`<section class="card ${cls}"><h2>${esc(title)}</h2>${body}</section>`;
const metric=(label,value,sub)=>`<div class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`;
const overviewResearchPrompt=p=>`Research the Overview of ${p.name} (${p.country}). Establish the current project identity, owner/developer, location, capacity, technology, development stage, partnership availability and latest dated status. Use primary official sources first, then authoritative regulatory, company, tender and market sources. Separate confirmed facts from reported claims and unresolved items. Return proposed Overview field updates with source URLs, publication dates and confidence; do not infer ownership, openness or capacity.`;
const overviewResearchState=p=>{const saved=note(p).overviewResearch;const completedDrin=p.id==='drin'?{status:'Completed',requestedAt:'2026-10-17',completedAt:'2026-10-17',findings:['FEKA officially identifies an ongoing estimated 68.40 MW wind investment project in Vau i Dejës.','FEKA states the 68.40 MW total covers three Albanian wind projects after preliminary investigation and wind measurements.','The Albanian Energy Regulatory Authority lists 17.1 MW HTT, 22.8 MW YEL and 28.5 MW OLV; reconcile these entries with the Drin label before treating the project identity or allocation as confirmed.','The 68.4 MW RTB, permits, grid and turbine details are intermediary-reported and do not prove an open investment mandate.'],sources:['FEKA energy project page — https://www.feka.com/en/sectors/energy','FEKA Albania wind-investment announcement — https://feka.com/en/news/energy-investment-in-the-balkans','Albanian Energy Regulatory Authority annual report — https://www.ere.gov.al/media/files/2024/10/01/Anual_Report_2023.pdf','Current 68.4 MW intermediary RTB listing — https://dealstream.com/d/biz-sale/other-indust/vyjwzi'],prompt:overviewResearchPrompt(p)}:null;const run=completedDrin||(saved||p.overviewResearch);if(!run)return '<p class="muted">No Overview research run has been started.</p>';const findings=run.findings?.length?`<div class="research-findings"><strong>Findings</strong>${list(run.findings)}</div>`:'';const sources=run.sources?.length?`<div class="research-findings"><strong>Sources</strong>${list(run.sources.map(s=>typeof s==='string'?s:`${s.title} — ${s.url}`))}</div>`:'';return `<div class="research-run-status"><span class="pill ${run.status==='Completed'?'green':'amber'}">${esc(run.status||'Prepared')}</span><small>Requested ${esc(run.requestedAt||'date not recorded')}${run.completedAt?` · completed ${esc(run.completedAt)}`:''}</small></div><p class="muted">The run is scoped to Overview only. Results must be reviewed and approved before they change project data.</p>${findings}${sources}<details><summary>Research scope</summary><pre class="research-prompt">${esc(run.prompt||overviewResearchPrompt(p))}</pre></details>`;};
const overviewResearchCard=p=>card('Deep research · Overview',`${overviewResearchState(p)}<p><button class="primary" data-start-overview-research>${note(p).overviewResearch?'Start new Overview research':'Start Overview research'}</button></p>`,'research-run-card');
const evidenceId=()=>`ev-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
const evidenceRecords=p=>[...(p.sources||[]).map((s,index)=>({id:`source-${index}`,title:s.title,type:'Imported research source',date:s.date,status:'Imported · not revalidated',url:s.url,notes:'Imported project reference. Recheck the source and record the current finding before relying on it.',readonly:true})),...(Array.isArray(note(p).evidence)?note(p).evidence:[])];
const evidenceForm=entry=>`<div class="evidence-form-grid"><label>Evidence title<input id="evidence-title" value="${esc(entry?.title||'')}" placeholder="e.g. Government approval record"></label><label>Evidence type<select id="evidence-type"><option ${entry?.type==='Official project source'?'selected':''}>Official project source</option><option ${entry?.type==='Government / regulatory'?'selected':''}>Government / regulatory</option><option ${entry?.type==='Commercial / offtake'?'selected':''}>Commercial / offtake</option><option ${entry?.type==='Ownership / corporate'?'selected':''}>Ownership / corporate</option><option ${entry?.type==='Media / market signal'?'selected':''}>Media / market signal</option><option ${entry?.type==='Other'?'selected':''}>Other</option></select></label><label>Date or period<input id="evidence-date" value="${esc(entry?.date||'')}" placeholder="YYYY-MM-DD or publication period"></label><label>Status<select id="evidence-status"><option ${entry?.status==='Confirmed'?'selected':''}>Confirmed</option><option ${entry?.status==='Reported · verify'?'selected':''}>Reported · verify</option><option ${entry?.status==='Contradicted'?'selected':''}>Contradicted</option><option ${entry?.status==='Pending review'?'selected':''}>Pending review</option></select></label><label class="evidence-url-field">Source URL<input id="evidence-url" type="url" value="${esc(entry?.url||'')}" placeholder="https://…"></label><label class="evidence-notes-field">What this supports<textarea id="evidence-notes" rows="4" placeholder="Record the claim supported, relevant entity, limitations and any conflict…">${esc(entry?.notes||'')}</textarea></label></div><input type="hidden" id="evidence-id" value="${esc(entry?.id||'')}"><p><button class="primary" id="save-evidence">${entry?'Update evidence':'Save evidence'}</button>${entry?'<button id="cancel-evidence">Cancel</button>':''}</p>`;
function evidenceEntry(item){const tone=item.status==='Confirmed'?'green':item.status==='Contradicted'?'red':'amber';return `<article class="evidence-entry"><div class="evidence-entry-head"><div><span class="pill">${esc(item.type||'Evidence')}</span> <span class="pill ${tone}">${esc(item.status||'Pending review')}</span><h3>${esc(item.title)}</h3></div>${item.readonly?'':`<div class="evidence-entry-actions"><button data-edit-evidence="${esc(item.id)}">Edit</button><button data-remove-evidence="${esc(item.id)}" class="danger-button">Remove</button></div>`}</div><div class="evidence-meta">${esc(item.date||'Date not recorded')} ${item.url?' · '+link(item.url,'Open source ↗'):''}</div><p>${esc(item.notes||'No supporting note recorded.')}</p></article>`;}
function evidenceSection(p){const records=evidenceRecords(p);return card('Evidence register',`<p class="muted">Keep project facts, ownership, approvals, commercial signals and supporting links here. Imported sources are read-only; added evidence is saved in this browser for this project.</p>${records.length?'<div class="evidence-list">'+records.map(evidenceEntry).join('')+'</div>':'<div class="empty">No evidence has been added yet.</div>'}`,'evidence-register')+card('Add project evidence',evidenceForm(null),'evidence-editor');}
function configurePortfolioViewport(){
  document.body.classList.add('portfolio-view');
  const content=$('#content');
  const summary=document.createElement('details');
  summary.className='portfolio-summary';
  const toggle=document.createElement('summary');
  toggle.textContent='Portfolio summary & research notes · imported data, not live-verified';
  summary.appendChild(toggle);
  const info=document.createElement('div');
  info.className='portfolio-summary-content';
  for(const selector of ['.metrics','.notice','.status-legend'])info.appendChild(content.querySelector(selector));
  summary.appendChild(info);
  content.querySelector('.section-head').before(summary);
}
function searchableProjectText(p){const contactText=contactDesk.contacts(p).flatMap(c=>[c.name,c.title,c.role,c.linkedin,c.source,c.notes,...(c.emails||[]),...(c.phones||[])].filter(Boolean));return [p.name,p.developer,p.country,p.capacity,p.signal,p.summary,p.stage,p.partnership,p.location,p.technology,p.next,...(p.gaps||[]),...contactText].filter(Boolean).join(' ').toLowerCase();}
let countryMode='exclude',countryValues=[];
const countryMatches=p=>!countryValues.length||(countryMode==='exclude'?!countryValues.includes(p.country):countryValues.includes(p.country));
function setupCountryFilter(){const old=$('#country');if(!old)return;old.outerHTML='<div class="country-filter" id="country-filter"><button id="country-trigger" type="button" aria-haspopup="listbox" aria-expanded="false">All countries⌄</button><div id="country-menu" class="country-menu" hidden><div class="country-mode" role="group" aria-label="Country filter mode"><button type="button" data-country-mode="include">Include</button><button type="button" data-country-mode="exclude" class="selected">Exclude</button></div><div id="country-options" class="country-options" role="listbox" aria-label="Countries"></div><button type="button" id="country-clear" class="country-clear">Clear countries</button></div></div>';const countries=[...new Set(projects.map(p=>p.country))].sort();$('#country-options').innerHTML=countries.map(country=>`<label><input type="checkbox" data-country-option="${esc(country)}"><span>${esc(country)}</span></label>`).join('');const refresh=()=>{const label=countryValues.length?`${countryMode==='exclude'?'Except ':'Only '}${countryValues.length===1?countryValues[0]:countryValues.length+' countries'}`:'All countries';$('#country-trigger').textContent=label+'⌄';document.querySelectorAll('[data-country-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.countryMode===countryMode));document.querySelectorAll('[data-country-option]').forEach(i=>i.checked=countryValues.includes(i.dataset.countryOption));sidebar();if(!current)portfolio();};$('#country-trigger').addEventListener('click',()=>{$('#country-menu').hidden=!$('#country-menu').hidden;$('#country-trigger').setAttribute('aria-expanded',String(!$('#country-menu').hidden));});$('#country-clear').addEventListener('click',()=>{countryValues=[];refresh();});document.addEventListener('click',e=>{const filter=e.target.closest('#country-filter');if(!filter){const menu=$('#country-menu');if(menu&&!menu.hidden){menu.hidden=true;$('#country-trigger').setAttribute('aria-expanded','false');}}});document.addEventListener('click',e=>{const mode=e.target.closest('[data-country-mode]');if(mode){countryMode=mode.dataset.countryMode;refresh();return;}const option=e.target.closest('[data-country-option]');if(option){countryValues=option.checked?[...countryValues,option.dataset.countryOption]:countryValues.filter(v=>v!==option.dataset.countryOption);refresh();}});refresh();}
function filtered(){const q=$('#search').value.trim().toLowerCase();return pipelineProjects(projects.filter(p=>(countryMatches(p))&&(!$('#signal').value||p.signal===$('#signal').value)&&(!q||searchableProjectText(p).includes(q))));}
function sidebar(){const rows=orderedProjects(filtered());$('#projects').innerHTML=rows.length?rows.map(p=>`<div class="project-item ${note(p).priority?'starred':''}" draggable="true" data-drag-project="${p.id}"><span class="project-drag-handle" title="Drag to reorder" aria-hidden="true">⠿</span><button class="project-link ${current===p.id?'active':''}" data-project="${p.id}" ${current===p.id?'aria-current="page"':''}>${esc(p.name)}<small>${esc(p.country)} · ${esc(p.developer)}</small></button>${emailStatusMark(p)}${emailVerificationMark(p)}${opportunityMark(p)}<button class="project-star" data-star="${p.id}" aria-label="${note(p).priority?'Remove '+esc(p.name)+' from starred projects':'Star '+esc(p.name)+' and keep it at the top'}" aria-pressed="${!!note(p).priority}" title="${note(p).priority?'Unstar project':'Star project'}">${note(p).priority?'★':'☆'}</button></div>`).join(''):'<div class="empty">No projects match these filters.</div>';$('#total').textContent=projects.length;}
function navigate(id,newTab='Overview'){current=projects.some(p=>p.id===id)?id:null;tab=tabs.includes(newTab)?newTab:'Overview';history.replaceState(null,'',current?`#${current}/${encodeURIComponent(tab)}`:'#portfolio');render();window.scrollTo({top:0});}
function portfolio(){const rows=filtered();$('#breadcrumb').textContent='Portfolio overview';$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">GLOBAL WIND · RESEARCH WORKSPACE</div><h1>Opportunity starts with clarity.</h1><p class="intro">One place to review projects, understand partnership signals and turn unanswered questions into the next conversation.</p></div><span class="pill">LOCAL EDITION / 01</span></div><div class="metrics">${metric('Projects in library',projects.length,'Individual assets + portfolios')}${metric('Countries',new Set(projects.map(p=>p.country)).size,'Global opportunity coverage')}${metric('Prioritised',projects.filter(p=>note(p).priority).length,'Your manually starred projects')}${metric('Deliverable mailboxes',contactDesk.verifiedCount(),'Reoon positive · identity separate')}</div><div class="notice">Imported research leads · ${importedOn}. Sources and availability have not been rechecked in this build. A reported process is not a confirmed open opportunity. Missing information stays unknown.</div><div class="section-head"><h2>Project pipeline</h2><small>${rows.length} of ${projects.length} projects · filter from the sidebar</small></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Developer</th><th>Country</th><th>Reported scale</th><th>Partnership Signal</th><th>Opportunity Status</th><th>Your workflow</th><th>Review</th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="table-project-name"><button class="table-star project-star" data-star="${p.id}" aria-label="${note(p).priority?'Unstar':'Star'} ${esc(p.name)}" aria-pressed="${!!note(p).priority}">${note(p).priority?'★':'☆'}</button><button class="text-button" data-project="${p.id}">${esc(p.name)}</button></span></td><td>${esc(p.developer)}</td><td>${esc(p.country)}</td><td>${esc(p.capacity)}</td><td>${pill(p.signal,color(p))}</td><td data-opportunity-status="${p.id}">${opportunityStatus(p)}</td><td>${pill(note(p).workflow||'Not contacted')}<small>${note(p).followup?`Follow-up: ${esc(note(p).followup)}`:'No follow-up set'}</small></td><td><button class="quiet" data-project="${p.id}" aria-label="Open ${esc(p.name)}">Open ↗</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No matching projects. Clear the sidebar filters.</div>'}</div><p class="status-legend">Sponsor invitation = invitation reported in prior research. Reported process = media or intermediary signal. Watchlist = no verified invitation. Procurement = formal tender route. ⊘ No current opportunity = counterparty reported no active opportunity at present.<br>Project scales are not aggregated: portfolios, batteries and wind capacity use different units and may overlap.</p>`;configurePortfolioViewport();enableColumnResize($('#content table'), $('#content .section-head'), msg);}
  const partnerFieldDefinitions=[
   ['company','Company'],['country','Country / region'],['industry','Industry'],['subsector','Sub-sector'],
   ['partnerType','Partner type'],['intent','Investment / JV intent'],['preferredScale','Preferred project scale'],
   ['preferredGeography','Preferred geography'],['preferredStage','Preferred project stage'],['evidenceDate','Latest evidence date'],
   ['evidenceSummary','Evidence summary'],['sources','Source links'],['contactName','Decision-maker name'],
   ['contactRole','Designation / role'],['linkedin','LinkedIn profile'],['email','Business email'],['phone','Phone'],
   ['verificationStatus','Contact verification status'],['status','Partnership status'],['lastInteraction','Last interaction date'],
   ['responseSummary','Response summary'],['referralRoute','Referral route'],['nextAction','Next action'],['notes','Notes']
  ];
  const partnerStatusOptions=['Open — actively seeking investment/JV','Potential fit — intent identified, availability unconfirmed','Engaged — already contacted or in discussion','No current opening — not accepting opportunities now','Referral route — directed us to another person/company','Not a fit — scope or geography does not match','Historical — previously active, current intent unconfirmed','Researching — insufficient evidence','Do not contact — explicit restriction'];
  let partnerTab='Overview';
  function legacyPartnerPanel(){const content={
   'Overview':card('Partner overview',`<p>Partner records will use the same overview structure as Wind Projects: current intent, preferred scale, geography, evidence level and relationship status.</p>${facts([['Partner records',`${partnerRecords.length} currently added`],['Evidence standard','Dated, source-backed intent required'],['Relationship history','Engaged, referral and no-opening outcomes retained']])}`)+card('What will be established',list(['Current investment or JV mandate.','Preferred project scale, stage and geography.','Decision-maker route and contact verification.','Latest response, referral and next action.'])),
   'Project & Status':card('Partner profile & status',facts([['Company','Not yet added'],['Industry / sub-sector','Not yet established'],['Partner type','Investor, developer, utility or strategic partner'],['Preferred project scale','Not yet established'],['Preferred geography','Not yet established'],['Partnership status','Researching — insufficient evidence']]))+card('Status discipline',`<p class="muted">A company is not marked open from generic wind experience alone. The latest dated evidence and the exact source are retained with each record.</p>`),
   'Partnership':card('Investment & JV intent',`<p>Capture the partner’s stated route: investment, joint venture, co-development, acquisition, strategic alliance or referral.</p>${facts([['Current intent','Not yet researched'],['Participation route','Not yet established'],['Investment ticket / scale','Not yet established'],['Referral route','None recorded']])}`),
   'Financials':card('Financial fit',`<p class="muted">Financial information is recorded only when supported by public evidence or a counterparty response.</p>${facts([['Typical investment size','Not established'],['Capital structure preference','Not established'],['Return / acquisition criteria','Not established'],['Financial evidence','Not received or reviewed']])}`),
   'Due Diligence':card('Partner diligence checklist',`<p class="muted">These checks will be reviewed for each partner before classifying intent or fit.</p>${list(['Confirm legal entity and operating geography.','Confirm current investment or JV activity.','Confirm decision-maker authority and route.','Check latest evidence date and source.','Record any no-opening or referral response.'])}`),
   'Evidence':card('Partner evidence register',`<p>Source links, publication dates, quoted intent and response evidence will be attached here. Unverified claims remain clearly marked.</p><div class="empty">No partner evidence added yet.</div>`),
   'History':card('Relationship history',`<p>Prior contact, engagement, referrals, no-opening responses and future follow-up actions will remain visible here.</p><div class="empty">No partner interaction history yet.</div>`),
   'Contacts':card('Partner contacts',`<p>Decision-makers, business emails, phone numbers, LinkedIn profiles and verification results will use the same contact-card pattern as Wind Projects.</p><div class="empty">No partner contacts added yet.</div>`),
   'Research & Sources':card('Partner research brief',`<p>Research will be consolidated into industry, investment intent, preferred scale, geography, evidence and source links.</p><div class="empty">No partner research completed yet.</div>`),
   'Outreach':card('Partner outreach',`<p>Personalised outreach drafts, recipient selection, email status, responses, referrals and next actions will follow the Wind Projects outreach workflow.</p><div class="empty">No partner outreach draft yet.</div>`)
  };return content[partnerTab]||content.Overview;}
function ensureLibraryToggle(){if($('#library-toggle'))return;const anchor=$('#portfolio-button');if(!anchor)return;anchor.insertAdjacentHTML('afterend','<div id="library-toggle" class="library-toggle" role="radiogroup" aria-label="Wind workspace library"><button type="button" data-library="projects" role="radio" aria-checked="true">◉ Wind Projects</button><button type="button" data-library="partners" role="radio" aria-checked="false">○ Investors &amp; JV Partners</button></div>');}
function switchLibrary(mode){libraryMode=mode==='partners'?'partners':'projects';current=null;partnerCurrent=null;tab='Overview';partnerTab='Overview';history.replaceState(null,'',libraryMode==='partners'?'#partners':'#portfolio');render();window.scrollTo({top:0});}
  function legacyPartnerLibrary(){$('#breadcrumb').textContent='Investors & JV Partners';$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">GLOBAL WIND · PARTNER RESEARCH</div><h1>Investors &amp; JV Partners</h1><p class="intro">A separate library for developers, investors, utilities and strategic partners with current, source-backed wind investment or partnership intent.</p></div><span class="pill">SOURCE-BACKED ONLY</span></div><div class="notice">No company is classified as actively seeking a wind investment or JV without dated evidence. Generic wind experience is not treated as current intent.</div><div class="section-head"><h2>Partner pipeline</h2><small>${partnerRecords.length} partner records</small></div><div class="card partner-empty"><h2>No partner records yet</h2><p>Partner records will appear here after their investment mandate, preferred geography, project stage and decision-maker route have been verified.</p><button class="primary" type="button" data-partner-research>Prepare partner research</button></div><div class="tabs partner-tabs" role="tablist" aria-label="Partner sections">${tabs.map(t=>`<button role="tab" aria-selected="${t===partnerTab}" class="tab ${t===partnerTab?'selected':''}" data-partner-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="partner-panel" role="tabpanel">${legacyPartnerPanel()}</div><div class="card partner-schema"><div class="section-head"><h2>Partner record structure</h2><small>${partnerFieldDefinitions.length} fields</small></div><p class="muted">Every record will preserve both active opportunities and relationship history, including referrals and companies with no current opening.</p><div class="partner-field-list">${partnerFieldDefinitions.map(([key,label])=>`<span class="partner-field" data-field="${key}">${esc(label)}</span>`).join('')}</div><p class="muted partner-status-list"><strong>Status values:</strong> ${partnerStatusOptions.map(esc).join(' · ')}</p></div>`;}
 let partnerCurrent=null;
function partnerOrder(){const ids=partnerRecords.map(p=>p.id),stored=Array.isArray(saved.partnerOrder)?saved.partnerOrder:[];return [...stored.filter(id=>ids.includes(id)),...ids.filter(id=>!stored.includes(id))];}
function partnerMatches(){const q=($('#search')?.value||'').trim().toLowerCase();if(!q)return partnerRecords.slice();return partnerRecords.filter(p=>[p.company,p.country,p.industry,p.subSector,p.partnerType,p.intent,p.scale,p.stage,p.status,p.summary,p.contact,p.next,p.notes,...(partnerContacts[p.id]||[]).flatMap(c=>[c.name,c.title,c.role,c.email,c.businessEmail,c.personalEmail,c.linkedin,c.phone,c.verification,c.source])].filter(Boolean).join(' ').toLowerCase().includes(q));}
function orderedPartners(matches){const order=partnerOrder(),position=new Map(order.map((id,index)=>[id,index]));const byPosition=(a,b)=>(position.get(a.id)??Number.MAX_SAFE_INTEGER)-(position.get(b.id)??Number.MAX_SAFE_INTEGER);return matches.filter(p=>note(p).priority).sort(byPosition).concat(matches.filter(p=>!note(p).priority).sort(byPosition));}
function partnerVerificationMark(p){const reoonCount=partnerDesk.verifiedCount(asPartner(p));if(reoonCount)return `<span class="sidebar-verification" title="${reoonCount} verified email${reoonCount===1?'':'s'}" aria-label="${reoonCount} verified email${reoonCount===1?'':'s'}">${reoonCount>1?'✓✓':'✓'}</span>`;const contacts=partnerContacts[p.id]||[],emails=contacts.filter(c=>c.personalEmail||c.businessEmail||c.email),verified=contacts.filter(c=>c.verified===true||/reoon|deliverable|verified/i.test(c.verification||'')&&!/not independently|not identified|not found|unverified/i.test(c.verification||''));if(verified.length)return `<span class="sidebar-verification" title="${verified.length} verified email${verified.length===1?'':'s'}" aria-label="${verified.length} verified email${verified.length===1?'':'s'}">${verified.length>1?'✓✓':'✓'}</span>`;return emails.length?'<span class="sidebar-verification pending" title="Email saved; no deliverable verification result" aria-label="Email saved; no deliverable verification result">✓</span>':'';}
const partnerContactCards=p=>(partnerContacts[p.id]||[]).map(c=>`<article class="card"><div class="avatar">${esc(c.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</div><h3>${esc(c.name)}</h3><p class="contact-role">${esc(c.title)}</p><p>${esc(c.role)}</p><p><strong>Personal email:</strong> ${c.personalEmail?esc(c.personalEmail):'No public personal email found'}</p><p><strong>Business email:</strong> ${c.businessEmail?esc(c.businessEmail):'Not found'}</p><p><strong>Generic company route:</strong> ${c.email?esc(c.email):'Not found'}</p><p>${c.phone?`<strong>Phone:</strong> ${esc(c.phone)}`:'Phone not recorded'}</p><p class="muted">${esc(c.verification)}</p><div class="contact-link">${c.linkedin?`<a href="${c.linkedin}" target="_blank" rel="noreferrer">LinkedIn profile ↗</a>`:'LinkedIn not recorded'}</div><div class="contact-link"><a href="${c.source}" target="_blank" rel="noreferrer">Contact source ↗</a></div></article>`).join('');
 const partnerCompanyLinkedins={
  'sermsang-power':'https://www.linkedin.com/company/sermsang-power-corporation-pcl-ssp',
  'acen':'https://www.linkedin.com/company/officialacen/',
  'terrawind':'https://www.linkedin.com/company/terrawind-renewables-inc',
  'ix-renewables':'https://www.linkedin.com/company/ixrenewables-bv/',
  'pc1-group':'https://www.linkedin.com/company/pc1'
 };
 const partnerLinks=p=>(p.sources||[]).map(u=>`<li><a href="${u}" target="_blank" rel="noreferrer">${u}</a></li>`).join('');
 function partnerDraft(p){return `Subject: ${p.company} — Wind investment and partnership enquiry\n\nDear ${p.company} team,\n\nI am advising an established renewable-energy developer on selected international opportunities for equity investment, joint ventures and strategic participation.\n\nI am contacting you regarding ${p.company} and would appreciate a brief, non-confidential overview of your current investment or partnership priorities, including suitable project stages, geographies, capacity ranges and the correct route for a potential introduction.\n\nOur partner is evaluating wind projects and platforms for equity investment, joint ventures, co-development and strategic participation. We would be pleased to share a short project profile after confirming the appropriate contact and any confidentiality requirements.\n\nCould you please direct this enquiry to the person responsible for investment, corporate development, partnerships or project finance?\n\nKind regards,`;} 
 const partnerDiligence=[['partnerIdentity','Legal entity and operating geography confirmed.'],['partnerIntent','Current investment or JV activity identified.'],['partnerOpening','Whether a new partner window exists is confirmed.'],['partnerAuthority','Decision-maker authority and route verified.'],['partnerEvidence','Latest source date and relationship status retained.']];
 function partnerDiligenceCard(p){return card('Partner diligence checklist',`<p class="muted">Ticking a question records review only; it does not certify that the partner or opportunity passed diligence.</p>${partnerDiligence.map(([key,label])=>`<label class="check-row"><input type="checkbox" data-partner-check="${key}" ${note(p).partnerChecks?.[key]?'checked':''}><span>${esc(label)}<small>Record the supporting source or unresolved issue in the notes below.</small></span></label>`).join('')}<label for="partner-diligence-notes"><h3>Findings & evidence gaps</h3></label><textarea id="partner-diligence-notes" placeholder="Record documents reviewed, source links, findings and open questions…">${esc(note(p).partnerDiligenceNotes||'')}</textarea><p><button class="primary" id="save-partner-diligence">Save review notes</button></p>`);}
 function partnerEvidenceForm(p){const entry=note(p).partnerEvidenceDraft||{};return `<div class="evidence-form-grid"><label>Evidence title<input id="partner-evidence-title" value="${esc(entry.title||'')}" placeholder="e.g. Official partnership mandate"></label><label>Evidence type<select id="partner-evidence-type"><option>Official project source</option><option>Government / regulatory</option><option>Ownership / corporate</option><option>Media / market signal</option><option>Contact / response</option><option>Other</option></select></label><label>Date or period<input id="partner-evidence-date" value="${esc(entry.date||'')}" placeholder="YYYY-MM-DD or publication period"></label><label>Status<select id="partner-evidence-status"><option>Confirmed</option><option>Reported · verify</option><option>Contradicted</option><option>Pending review</option></select></label><label class="evidence-url-field">Source URL<input id="partner-evidence-url" type="url" value="${esc(entry.url||'')}" placeholder="https://…"></label><label class="evidence-notes-field">What this supports<textarea id="partner-evidence-notes" rows="4" placeholder="Record the claim supported, relevant entity, limitations and any conflict…">${esc(entry.notes||'')}</textarea></label></div><p><button class="primary" id="save-partner-evidence">Save evidence</button></p>`;}
 function partnerEvidenceEntries(p){const entries=Array.isArray(note(p).partnerEvidence)?note(p).partnerEvidence:[];return entries.length?`<div class="evidence-list">${entries.map(item=>`<article class="evidence-entry"><div class="evidence-entry-head"><div><span class="pill">${esc(item.type||'Evidence')}</span> <span class="pill amber">${esc(item.status||'Pending review')}</span><h3>${esc(item.title)}</h3></div><button data-remove-partner-evidence="${esc(item.id)}" class="danger-button">Remove</button></div><div class="evidence-meta">${esc(item.date||'Date not recorded')} ${item.url?' · '+link(item.url,'Open source ↗'):''}</div><p>${esc(item.notes||'No supporting note recorded.')}</p></article>`).join('')}</div>`:'<div class="empty">No partner evidence has been added yet.</div>';}
 function partnerResearchNotesCard(p){return card('Additional research notes',`<label class="sr-only" for="partner-research-notes">Partner research notes</label><textarea id="partner-research-notes" placeholder="Add dated research, citations and conflicting information…">${esc(note(p).partnerResearchNotes||'')}</textarea><p><button class="primary" id="save-partner-research">Save research notes</button></p>`);}
 function partnerPanel(){const p=partnerCurrent;if(!p)return card('Partner pipeline',`<p>Select a company from the left library to review its complete record.</p>${facts([['Partner records',`${partnerRecords.length} currently added`],['Provider gates','ChatGPT research · Exa · Firecrawl hosted search'],['Contact status','No person-email matches verified in this run']])}`);const sourceCard=card('Sources',`<ol>${partnerLinks(p)}</ol>`);const content={
  'Overview':card('Investment snapshot',`<p>${esc(p.summary)}</p>${facts([['Partnership status',p.status],['Latest evidence',p.latestEvidence],['Research completeness','Initial multi-source brief · route still to verify'],['Provider record','ChatGPT + Exa + Firecrawl hosted search']])}`)+card('Recommended next step',`<p>${esc(p.next)}</p>`,'action-card'),
  'Project & Status':card('Partner profile & status',facts([['Company',p.company],['Country / region',p.country],['Industry / sub-sector',`${p.industry} / ${p.subSector}`],['Partner type',p.partnerType],['Preferred project scale',p.scale],['Preferred project stage',p.stage],['Partnership status',p.status]])),
  'Partnership':card('Investment & JV intent',`<p>${esc(p.intent)}</p>${facts([['Participation route',p.partnerType],['Investment / JV scale',p.scale],['Referral route',p.next]])}`),
  'Financials':card('Financial fit',`<p class="muted">No investment ticket, valuation, capital structure or return criteria were published in the reviewed sources. No terms are inferred.</p>${facts([['Financial status','Not publicly disclosed'],['Investment size',p.scale],['Commercial caution','Confirm mandate directly before outreach']])}`),
  'Due Diligence':partnerDiligenceCard(p),
  'Evidence':card('Partner evidence register',`<p>Source-backed claims, responses and relationship evidence are preserved with dates. Imported sources remain visible below; added evidence is saved locally for this partner.</p>${partnerEvidenceEntries(p)}${facts([['Latest evidence date',p.latestEvidence],['Evidence confidence','Medium to high depending on source'],['Unresolved','Open mandate and decision-maker route']])}`)+card('Add partner evidence',partnerEvidenceForm(p),'evidence-editor')+sourceCard,
  'History':card('Relationship history',`<p>${esc(p.notes)}</p>${facts([['Last interaction',note(p).lastInteraction||'No direct interaction recorded'],['Response summary',note(p).responseSummary||'No response received'],['Research checkpoint','Completed with provider limits documented']])}<label for="partner-history-notes"><h3>Interaction and referral notes</h3></label><textarea id="partner-history-notes" placeholder="Record meetings, replies, referrals and next actions…">${esc(note(p).partnerHistoryNotes||'')}</textarea><p><button class="primary" id="save-partner-history">Save history notes</button></p>`),
  'Contacts':card('Research route',`<p>${esc(p.contact)}</p><p class="contact-link"><strong>Company LinkedIn page:</strong> ${partnerCompanyLinkedins[p.id]?`<a href="${partnerCompanyLinkedins[p.id]}" target="_blank" rel="noreferrer">Open company page ↗</a>`:'Not recorded'}</p>`)+partnerDesk.view(asPartner(p)).replace(/(<button data-edit-contact="([^"]+)" data-contact-project="([^"]+)"[^>]*>Edit contact<\/button>)/g,'$1<button class="danger-button" data-delete-contact="$2" data-contact-project="$3">Delete contact</button>'),
  'Research & Sources':card('Partner research brief',`<p>${esc(p.summary)}</p>${facts([['Search scope','Wind investors, developers and JV partners'],['ChatGPT','Completed'],['Exa','Completed'],['Firecrawl','Hosted search completed; plugin session unavailable'],['Sources reviewed',String((p.sources||[]).length)]])}`)+sourceCard+partnerResearchNotesCard(p),
  'Outreach':`<div class="two-col"><div>${card('Draft an introductory enquiry',`<p class="muted">Editable partner-specific draft. Confirm the route before sending and do not imply that this company has an open mandate. Start with a "Subject: …" line; Pulse adds your signature. Emails go out only when you click Send with Pulse below.</p><label class="sr-only" for="partner-draft">Partner email draft</label><textarea id="partner-draft" rows="15">${esc(note(p).partnerDraft??partnerDraft(p))}</textarea><p><button class="primary" id="save-partner-draft">Save draft</button> <button id="copy-partner-draft">Copy draft</button></p>`)}${partnerPulse.card(asPartner(p),note(p).partnerDraft??partnerDraft(p))}</div><div>${card('Your relationship workflow',`<div class="form-row"><label>Stage<select id="partner-workflow">${workflowStages.map(v=>`<option ${note(p).workflow===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Follow-up date<input type="date" id="partner-followup" value="${esc(note(p).followup||'')}"></label></div><label for="partner-email-status">Email status<select id="partner-email-status"><option value="" ${!note(p).emailStatus?'selected':''}>Not sent</option><option value="sent" ${note(p).emailStatus==='sent'?'selected':''}>Email sent</option><option value="responded" ${note(p).emailStatus==='responded'?'selected':''}>Response received</option></select></label><p class="outreach-status-help"><span class="email-status-dot sent"></span> Email sent &nbsp; <span class="email-status-dot responded"></span> Response received</p><label for="partner-outreach-notes">Conversation notes</label><textarea id="partner-outreach-notes" placeholder="Log actual correspondence, referrals and next actions…">${esc(note(p).outreachNotes||'')}</textarea><p><button class="primary" id="save-partner-outreach">Save workflow</button></p><p class="muted">Dates and outreach status are reminders in this workspace only. Emails are sent only through Send with Pulse; there are no scheduled notifications.</p>`)}</div></div>`
 };return content[partnerTab]||content.Overview;}
function partnerLibrary(){if(partnerCurrent){$('#breadcrumb').textContent=`${partnerCurrent.company} / ${partnerTab}`;$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">${esc(partnerCurrent.country)} · WIND PARTNER</div><h1>${esc(partnerCurrent.company)}</h1><p class="intro">${esc(partnerCurrent.partnerType)} <span class="slash">/</span> ${esc(partnerCurrent.scale)}</p><div class="summary-line"><span class="pill">${esc(partnerCurrent.status)}</span> · Latest evidence ${esc(partnerCurrent.latestEvidence)}</div></div><div class="heading-actions"><button id="export-project">Export partner</button></div></div><div class="tabs partner-tabs" role="tablist" aria-label="Partner sections">${tabs.map(t=>`<button role="tab" aria-selected="${t===partnerTab}" class="tab ${t===partnerTab?'selected':''}" data-partner-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="partner-panel" role="tabpanel">${partnerPanel()}</div>`;return;}$('#breadcrumb').textContent='Investors & JV Partners';$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">GLOBAL WIND · PARTNER RESEARCH</div><h1>Investors &amp; JV Partners</h1><p class="intro">Source-backed Asian companies with wind investment, development or JV evidence.</p></div><span class="pill">SOURCE-BACKED ONLY</span></div><div class="notice">No company is classified as actively seeking a wind investment or JV without dated evidence. Generic wind experience is not treated as current intent.</div><div class="section-head"><h2>Partner pipeline</h2><small>${partnerRecords.length} partner records</small></div><div class="partner-record-grid">${orderedPartners(partnerRecords).map(p=>`<button class="card partner-record" type="button" data-partner-record="${p.id}"><div class="eyebrow">${esc(p.country)}</div><h2>${esc(p.company)}</h2><p>${esc(p.summary)}</p><span class="pill">${esc(p.status)}</span><small>Evidence ${esc(p.latestEvidence)}</small></button>`).join('')}</div><div class="tabs partner-tabs" role="tablist" aria-label="Partner sections">${tabs.map(t=>`<button role="tab" aria-selected="${t===partnerTab}" class="tab ${t===partnerTab?'selected':''}" data-partner-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="partner-panel" role="tabpanel">${partnerPanel()}</div>`;}
const renderProjectsSidebar=sidebar;sidebar=()=>{ensureLibraryToggle();document.body.classList.toggle('partners-mode',libraryMode==='partners');if(libraryMode==='partners'){const rows=orderedPartners(partnerMatches());$('#projects').innerHTML=rows.length?rows.map(p=>`<div class="project-item partner-item ${note(p).priority?'starred':''}" draggable="true" data-drag-partner="${p.id}"><span class="project-drag-handle" title="Drag to reorder" aria-hidden="true">⠿</span><button class="partner-sidebar-record project-link ${partnerCurrent?.id===p.id?'selected':''}" type="button" data-partner-record="${p.id}" ${partnerCurrent?.id===p.id?'aria-current="page"':''}><strong>${esc(p.company)}</strong><span>${esc(p.country)} · ${esc(p.status.split(' — ')[0])}</span></button>${emailStatusMark(p)}${partnerVerificationMark(p)}<button class="project-star partner-star" data-partner-star="${p.id}" aria-label="${note(p).priority?'Remove '+esc(p.company)+' from starred partners':'Star '+esc(p.company)+' and keep it at the top'}" aria-pressed="${!!note(p).priority}" title="${note(p).priority?'Unstar partner':'Star partner'}">${note(p).priority?'★':'☆'}</button></div>`).join(''):'<div class="empty">No partners match this search.</div>';$('#total').textContent=partnerRecords.length;return;}renderProjectsSidebar();};
const renderProjectsPortfolio=portfolio;portfolio=()=>libraryMode==='partners'?partnerLibrary():renderProjectsPortfolio();
function header(p){return `<div class="heading"><div><div class="eyebrow">${esc(p.country)} / WIND OPPORTUNITY</div><h1><button class="detail-star project-star" data-star="${p.id}" aria-label="${note(p).priority?'Unstar':'Star'} ${esc(p.name)}" aria-pressed="${!!note(p).priority}" title="${note(p).priority?'Unstar project':'Star project'}">${note(p).priority?'★':'☆'}</button>${opportunityMark(p)}${esc(p.name)}</h1><p class="intro">${esc(p.developer)} <span class="slash">/</span> ${esc(p.capacity)}</p><div class="summary-line">${pill(p.signal,color(p))} &nbsp; ${note(p).noOpportunity?'<span class="opportunity-summary">No current opportunity</span> · ':''}Research imported ${importedOn} · live verification pending</div></div><div class="heading-actions"><button id="star" aria-pressed="${!!note(p).priority}">${note(p).priority?'★ Prioritised':'☆ Prioritise'}</button><button class="opportunity-action" data-no-opportunity="${p.id}" aria-pressed="${!!note(p).noOpportunity}">${note(p).noOpportunity?'⊘ No current opportunity':'⊘ Mark no current opportunity'}</button><button id="export-project">Export project</button></div></div><div class="tabs" role="tablist" aria-label="Project sections">${tabs.map(t=>`<button role="tab" id="tab-${tabs.indexOf(t)}" aria-selected="${t===tab}" aria-controls="panel" tabindex="${t===tab?0:-1}" class="tab ${t===tab?'selected':''}" data-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div>`;}
function overview(p){return `<div class="two-col"><div>${card('Investment snapshot',`<p>${esc(p.summary)}</p>${facts([['Development status',p.stage],['Partnership availability',p.partnership],['Evidence level','Imported reference · not revalidated'],['Research completeness',p.id==='berwick-b'||p.id==='nose-hill'?'Expanded brief · diligence outstanding':'Initial brief · further research required']])}`)}${overviewResearchCard(p)}${card('What needs to be established',list(p.gaps))}</div><div>${card('Recommended next step',`<p>${esc(p.next)}</p><button class="primary" data-tab="Outreach">Prepare an enquiry →</button>`,'action-card')}${card('Research discipline',`<p>No opportunity is classified as currently open without a dated confirmation. No unpublished financial terms are inferred.</p><p class="muted">Contacts: ${contactDesk.contacts(p).length} recorded · ${contactDesk.verifiedCount(p)} deliverable mailboxes<br>Diligence questions reviewed: ${diligence.filter(([k])=>note(p).checks?.[k]).length} / ${diligence.length}</p><button data-tab="Due Diligence">Review checklist</button>`)}</div></div>`;}
function draft(p){return `Subject: ${p.name} — Strategic Investment and Partnership\n\nDear ${p.id==='berwick-b'?'Berwick Bank team':p.id==='nose-hill'?'Ms. Beckie':'Project Team'},\n\nI am advising an established wind-energy developer on selected international opportunities for equity investment, joint ventures and strategic participation.\n\nI am contacting you regarding ${p.name} and would appreciate a brief, non-confidential overview of the project’s current development stage, ownership structure, capital requirements and available partnership opportunities.\n\nFor your review, please find below a brief profile of the developer:\n\nOur partner is a renewable-energy developer with experience in utility-scale wind and hybrid projects, covering development, engineering, construction, grid integration, commissioning and operations. Its wider group has pursued technology partnerships, international development frameworks and acquisitions of operating wind and hydrogen assets. It is currently evaluating equity investments, joint ventures and strategic participation in suitable projects.\n\nPlease direct me to the appropriate person responsible for the project’s partner process.\n\nKind regards,`;} 
function section(p){switch(tab){
case 'Overview':return overview(p);
case 'Project & Status':return card('Project facts',facts([['Project',p.name],['Country / location',p.location||p.country+' — exact location to confirm'],['Developer / sponsor',p.developer],['Reported capacity',p.capacity],['Technology',p.technology||'Wind; configuration and approved layout to verify'],['Development status',p.stage],['Permits / land','Supporting documents not reviewed'],['Grid connection','Connection agreement not reviewed'],['Commercial operation','No confirmed COD recorded'],['Last live verification','Not performed in this build']]))+card('Evidence gaps',list(p.gaps));
case 'Partnership':return `<div class="two-col"><div>${card('Opportunity & transaction perimeter',`<p>${esc(p.summary)}</p>${facts([['Signal classification',p.signal],['Current availability',p.partnership],['Participation route',p.signal==='Procurement'?'Formal procurement / eligibility requirements':p.signal==='Watchlist'?'Exploratory only; no confirmed invitation':'Equity / JV scope to confirm'],['Technology alliance','No specific alliance mandate established'],['Stake / governance','Not confirmed; request transaction terms'],['Deadlines / eligibility','Not verified; obtain current process instructions']])}`)}</div><div>${card('Before requesting confidential details',list(['Confirm sponsor or adviser authority.','Request a short non-confidential overview.','Agree a mutual NDA before document exchange.','Clarify investment ticket, stake and decision timetable.']),'action-card')}</div></div>`;
case 'Financials':return card('Financial evidence',`<p class="muted">Reported amounts are imported claims, not investment advice or verified financial models. Undisclosed values are not zero.</p>${facts([...(p.financials.length?p.financials:[['Capital expenditure','Not established'],['Capital requirement','Not established']]),['Equity valuation / purchase price','Not established'],['IRR / returns','No supported return forecast'],['Financial model','Not received or reviewed']])}`)+card('Information to request',list(['Base-case model and assumptions, including wind yield and curtailment.','Capex, contingency, construction schedule and currency exposure.','Executed revenue contracts and financing commitments.','Equity ticket, governance, dilution and exit scenarios.']));
case 'Due Diligence':return card('Due-diligence review checklist',`<p class="muted">Ticking a question records that you have reviewed it. It does not certify that the project passed diligence. Record findings and evidence in your notes.</p>${diligence.map(([k,t,d])=>`<label class="check-row"><input type="checkbox" data-check="${k}" ${note(p).checks?.[k]?'checked':''}><span><strong>${esc(t)}</strong><small>${esc(d)}</small></span></label>`).join('')}<label for="diligence-notes"><h3>Findings & evidence gaps</h3></label><textarea id="diligence-notes" placeholder="Record documents reviewed, source links, findings and open questions…">${esc(note(p).diligenceNotes||'')}</textarea><p><button class="primary" id="save-diligence">Save review notes</button></p>`);
case 'Evidence':return evidenceSection(p);
case 'History':return card('Project history & future milestones',`<p class="muted">Dates below are imported research. Targets are not achieved milestones.</p><div class="timeline">${p.history.map(([d,t])=>`<div class="event"><small>${esc(d)}</small><p>${esc(t)}</p></div>`).join('')}<div class="event"><small>${importedOn} · workspace event</small><p>Record imported into the standalone research desk. This is not a new project announcement or live verification.</p></div></div>`);
case 'Contacts':return contactDesk.view(p).replace(/(<button data-edit-contact="([^"]+)" data-contact-project="([^"]+)"[^>]*>Edit contact<\/button>)/g,'$1<button class="danger-button" data-delete-contact="$2" data-contact-project="$3">Delete contact</button>');
case 'Research & Sources':return card('Research brief',`<p>${esc(p.summary)}</p><p class="muted">This is a structured consolidation of available earlier research, not a newly completed deep-research report. Source content, dates, current job titles and project availability must be rechecked.</p>${list(p.gaps)}`)+card('Source register',p.sources.map(s=>`<div class="source">${link(s.url,s.title+' ↗')}<small>${esc(s.date)} · imported ${importedOn} · not revalidated</small><small>${esc(s.url)}</small></div>`).join(''))+card('Additional research notes',`<label class="sr-only" for="research-notes">Additional research notes</label><textarea id="research-notes" placeholder="Add dated research, citations and conflicting information…">${esc(note(p).researchNotes||'')}</textarea><p><button class="primary" id="save-research">Save research notes</button></p>`);
case 'Outreach':return `<div class="two-col"><div>${card('Draft an introductory enquiry',`<p class="muted">Editable draft for this project. Start with a "Subject: …" line; Pulse adds your signature. Emails go out only when you click Send with Pulse below.</p><label class="sr-only" for="draft">Email draft</label><textarea id="draft" rows="15">${esc(note(p).draft??draft(p))}</textarea><p><button class="primary" id="save-draft">Save draft</button> <button id="copy-draft">Copy draft</button></p>`)}${pulseSend.card(p,note(p).draft??draft(p))}</div><div>${card('Your relationship workflow',`<div class="form-row"><label>Stage<select id="workflow">${workflowStages.map(v=>`<option ${note(p).workflow===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Follow-up date<input type="date" id="followup" value="${esc(note(p).followup||'')}"></label></div><label>Email status<select id="email-status"><option value="" ${!note(p).emailStatus?'selected':''}>Not sent</option><option value="sent" ${note(p).emailStatus==='sent'?'selected':''}>Email sent</option><option value="responded" ${note(p).emailStatus==='responded'?'selected':''}>Response received</option></select></label><p class="outreach-status-help"><span class="email-status-dot sent"></span> Email sent &nbsp; <span class="email-status-dot responded"></span> Response received</p><label for="outreach-notes">Conversation notes</label><textarea id="outreach-notes" placeholder="Log your actual correspondence and next actions…">${esc(note(p).outreachNotes||'')}</textarea><p><button class="primary" id="save-outreach">Save workflow</button></p><p class="muted">Dates and outreach status are reminders in this workspace only. Emails are sent only through Send with Pulse; there are no scheduled notifications.</p>`)}${card('Storage',`<p class="muted">Notes, priorities and drafts are stored in this browser on this localhost origin. Use Export workspace to keep a portable backup. They do not sync to other browsers or services.</p>`)}</div></div>`;
}}
function render(){document.body.classList.remove('portfolio-view');sidebar();if(!current)return portfolio();const p=projects.find(p=>p.id===current);$('#breadcrumb').textContent=p.name;$('#content').innerHTML=header(p)+`<div id="panel" role="tabpanel" aria-labelledby="tab-${tabs.indexOf(tab)}">${section(p)}</div>`;}
const renderProjectPage=render;render=()=>{ensureLibraryToggle();document.body.classList.toggle('partners-mode',libraryMode==='partners');renderProjectPage();document.querySelectorAll('[data-library]').forEach(button=>{const active=button.dataset.library===libraryMode;button.textContent=(active?'◉ ':'○ ')+(button.dataset.library==='projects'?'Wind Projects':'Investors & JV Partners');button.setAttribute('aria-checked',String(active));});};
function patch(values){if(!current&&libraryMode==='partners'&&partnerCurrent){saved[partnerCurrent.id]={...saved[partnerCurrent.id],...values};return persist();}saved[current]={...saved[current],...values};return persist();}
function patchPartner(values){saved[partnerCurrent.id]={...saved[partnerCurrent.id],...values};return persist();}
function download(name,payload){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{
const partnerStar=e.target.closest('[data-partner-star]');if(partnerStar&&libraryMode==='partners'){const id=partnerStar.dataset.partnerStar;const p=partnerRecords.find(item=>item.id===id);if(p){saved[id]={...saved[id],priority:!note(p).priority};if(persist()){sidebar();msg(note(p).priority?'Partner starred and moved to the top.':'Partner unstarred.');}}return;}
const star=e.target.closest('[data-star]');if(star){const id=star.dataset.star;const p=projects.find(item=>item.id===id);if(p){saved[id]={...saved[id],priority:!note(p).priority};if(persist()){sidebar();if(!current)portfolio();else render();msg(note(p).priority?'Project starred and moved to the top.':'Project unstarred.');}}return;}
const noOpportunity=e.target.closest('[data-no-opportunity]');if(noOpportunity){const id=noOpportunity.dataset.noOpportunity;const p=projects.find(item=>item.id===id);if(p){saved[id]={...saved[id],noOpportunity:!note(p).noOpportunity};if(persist()){sidebar();if(!current)portfolio();else render();msg(note(p).noOpportunity?'Marked as no current opportunity.':'No current opportunity mark removed.');}}return;}
const project=e.target.closest('[data-project]');if(project)return navigate(project.dataset.project);
const sectionButton=e.target.closest('[data-tab]');if(sectionButton){navigate(current,sectionButton.dataset.tab);$(`#tab-${tabs.indexOf(tab)}`)?.focus();return;}
const id=e.target.closest('button')?.id;
if(id==='portfolio-button'){if(libraryMode==='partners'){switchLibrary('partners');return;}return navigate(null);}
if(id==='export')return download('wind-projects-workspace.json',{schemaVersion:1,exportedAt:new Date().toISOString(),projects,contacts:contactDesk.snapshot(),notes:saved});
if(id==='import')return $('#import-file').click();
if(!current){if(libraryMode==='partners'&&partnerCurrent){if(id==='save-partner-draft'&&patch({partnerDraft:$('#partner-draft').value}))msg('Partner draft saved in this browser.');if(id==='copy-partner-draft'){try{await navigator.clipboard.writeText($('#partner-draft').value);msg('Partner draft copied. Nothing was sent.');}catch{msg('Select the draft text and copy it manually.');}}if(id==='save-partner-outreach'&&patch({workflow:$('#partner-workflow').value,followup:$('#partner-followup').value,emailStatus:$('#partner-email-status').value,outreachNotes:$('#partner-outreach-notes').value}))msg('Partner workflow saved in this browser.');if(id==='save-partner-diligence'&&patch({partnerDiligenceNotes:$('#partner-diligence-notes').value}))msg('Partner diligence notes saved.');if(id==='save-partner-history'&&patch({partnerHistoryNotes:$('#partner-history-notes').value}))msg('Partner history notes saved.');if(id==='save-partner-research'&&patch({partnerResearchNotes:$('#partner-research-notes').value}))msg('Partner research notes saved.');if(id==='save-partner-evidence'){const title=$('#partner-evidence-title').value.trim(),url=$('#partner-evidence-url').value.trim();if(!title){msg('Add an evidence title before saving.');return;}if(url&&!/^https:\/\//i.test(url)){msg('Source URL must begin with https://.');return;}const records=Array.isArray(note(partnerCurrent).partnerEvidence)?note(partnerCurrent).partnerEvidence.slice():[];records.push({id:`partner-evidence-${Date.now()}`,title,type:$('#partner-evidence-type').value,date:$('#partner-evidence-date').value.trim(),status:$('#partner-evidence-status').value,url,notes:$('#partner-evidence-notes').value.trim()});if(patch({partnerEvidence:records})){render();msg('Partner evidence saved in this browser.');}}const removePartnerEvidence=e.target.closest('[data-remove-partner-evidence]');if(removePartnerEvidence){const records=(note(partnerCurrent).partnerEvidence||[]).filter(item=>item.id!==removePartnerEvidence.dataset.removePartnerEvidence);if(patch({partnerEvidence:records})){render();msg('Partner evidence removed.');}}return;}}
const p=projects.find(p=>p.id===current);
const overviewResearch=e.target.closest('[data-start-overview-research]');
if(overviewResearch){
 const active=projects.find(item=>item.id!==p.id&&note(item).overviewResearch?.status==='Queued');
 if(active){msg(`Finish the queued Overview research for ${active.name} before starting another tab.`);return;}
 const run={id:`overview-${Date.now()}`,status:'Queued',requestedAt:new Date().toISOString(),prompt:overviewResearchPrompt(p)};
 if(patch({overviewResearch:run})){render();msg('Overview research request saved. Results will require review before applying.');}
 return;
}
if(id==='star'){patch({priority:!note(p).priority});render();}
if(id==='export-project')download(p.id+'.json',{schemaVersion:1,exportedAt:new Date().toISOString(),project:p,contacts:contactDesk.contacts(p),verification:contactDesk.snapshot().checks,notes:{[p.id]:note(p)}});
if(id==='save-diligence'&&patch({diligenceNotes:$('#diligence-notes').value}))msg('Review notes saved in this browser.');
if(id==='save-research'&&patch({researchNotes:$('#research-notes').value}))msg('Research notes saved in this browser.');
if(id==='save-evidence'){
 const title=$('#evidence-title').value.trim(),url=$('#evidence-url').value.trim(),existingId=$('#evidence-id').value;
 if(!title){msg('Add an evidence title before saving.');return;}
 if(url&&!/^https:\/\//i.test(url)){msg('Source URL must begin with https://.');return;}
 const entry={id:existingId||evidenceId(),title,type:$('#evidence-type').value,date:$('#evidence-date').value.trim(),status:$('#evidence-status').value,url,notes:$('#evidence-notes').value.trim()};
 const records=Array.isArray(note(p).evidence)?note(p).evidence.slice():[];const index=records.findIndex(item=>item.id===entry.id);if(index>=0)records[index]=entry;else records.push(entry);
 if(patch({evidence:records})){render();msg(index>=0?'Evidence updated.':'Evidence saved in this browser.');}return;
}
if(id==='cancel-evidence'){render();return;}
if(id==='save-draft'&&patch({draft:$('#draft').value}))msg('Draft saved. Nothing has been sent yet.');
if(id==='copy-draft'){try{await navigator.clipboard.writeText($('#draft').value);msg('Draft copied. Nothing has been sent yet.');}catch{msg('Select the draft text and copy it manually.');}}
if(id==='save-outreach'){if(patch({workflow:$('#workflow').value,followup:$('#followup').value,emailStatus:$('#email-status').value,outreachNotes:$('#outreach-notes').value}))msg('Workflow and email status saved in this browser.');}
const editEvidence=e.target.closest('[data-edit-evidence]');if(editEvidence&&current){const entry=(note(p).evidence||[]).find(item=>item.id===editEvidence.dataset.editEvidence);if(entry){document.querySelector('.evidence-editor')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('.evidence-editor').innerHTML=`<h2>Edit project evidence</h2>${evidenceForm(entry)}`;}return;}
const removeEvidence=e.target.closest('[data-remove-evidence]');if(removeEvidence&&current){const idToRemove=removeEvidence.dataset.removeEvidence;if(confirm('Remove this evidence entry from the project?')){const records=(note(p).evidence||[]).filter(item=>item.id!==idToRemove);if(patch({evidence:records})){render();msg('Evidence removed from this browser.');}}return;}
});
document.addEventListener('dragstart',e=>{const partner=e.target.closest('[data-drag-partner]');if(partner&&libraryMode==='partners'){dragPartner=partner.dataset.dragPartner;partner.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragPartner);return;}const item=e.target.closest('[data-drag-project]');if(!item)return;dragProject=item.dataset.dragProject;item.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragProject);});
document.addEventListener('dragover',e=>{const partner=e.target.closest('[data-drag-partner]');if(partner&&dragPartner){e.preventDefault();document.querySelectorAll('.partner-item.drag-over').forEach(el=>el.classList.remove('drag-over'));if(partner.dataset.dragPartner!==dragPartner)partner.classList.add('drag-over');return;}const item=e.target.closest('[data-drag-project]');if(!item||!dragProject)return;e.preventDefault();document.querySelectorAll('.project-item.drag-over').forEach(el=>el.classList.remove('drag-over'));if(item.dataset.dragProject!==dragProject)item.classList.add('drag-over');});
document.addEventListener('drop',e=>{const partnerTarget=e.target.closest('[data-drag-partner]');if(partnerTarget&&dragPartner&&libraryMode==='partners'){e.preventDefault();const targetId=partnerTarget.dataset.dragPartner,from=partnerRecords.find(p=>p.id===dragPartner),to=partnerRecords.find(p=>p.id===targetId);if(!from||!to||from.id===to.id)return;if(!!note(from).priority!==!!note(to).priority){msg('Starred partners stay above unstarred partners. Reorder within each group.');return;}const ids=partnerOrder().filter(id=>id!==dragPartner);const targetIndex=ids.indexOf(targetId);ids.splice(targetIndex<0?ids.length:targetIndex,0,dragPartner);saved.partnerOrder=ids;if(persist()){sidebar();msg('Partner order saved.');}return;}const target=e.target.closest('[data-drag-project]');if(!target||!dragProject)return;e.preventDefault();const targetId=target.dataset.dragProject,from=projects.find(p=>p.id===dragProject),to=projects.find(p=>p.id===targetId);if(!from||!to||from.id===to.id)return;const fromNoOpportunity=!!note(from).noOpportunity,toNoOpportunity=!!note(to).noOpportunity;if(fromNoOpportunity!==toNoOpportunity){msg('No current opportunity projects stay at the bottom. Reorder within each group.');return;}if(!fromNoOpportunity&&!!note(from).priority!==!!note(to).priority){msg('Starred projects stay above unstarred projects. Reorder within each group.');return;}const ids=projectOrder().filter(id=>id!==dragProject);const targetIndex=ids.indexOf(targetId);ids.splice(targetIndex<0?ids.length:targetIndex,0,dragProject);saved.projectOrder=ids;if(persist()){sidebar();if(!current)portfolio();msg('Project order saved.');}});
document.addEventListener('dragend',()=>{dragProject=null;dragPartner=null;document.querySelectorAll('.project-item.dragging,.project-item.drag-over,.partner-item.dragging,.partner-item.drag-over').forEach(el=>el.classList.remove('dragging','drag-over'));});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')&&current)patch({checks:{...saved[current]?.checks,[e.target.dataset.check]:e.target.checked}});if(e.target.matches('[data-partner-check]')&&partnerCurrent)patch({partnerChecks:{...note(partnerCurrent).partnerChecks,[e.target.dataset.partnerCheck]:e.target.checked}});if(e.target.id==='email-status'&&current){const value=e.target.value;if(patch({emailStatus:value})){sidebar();msg(value==='responded'?'Response received status saved.':value==='sent'?'Email sent status saved.':'Email status cleared.');}}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const i=tabs.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;navigate(current,tabs[next]);$(`#tab-${next}`).focus();}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('File too large (5 MB maximum).');const data=JSON.parse(await f.text());if(data.schemaVersion!==1||!data.notes||typeof data.notes!=='object'||Array.isArray(data.notes))throw Error('Not a supported workspace export.');if(!confirm('Merge imported notes? Matching project notes will be replaced. Export your current workspace first if needed.'))return;for(const p of projects){const n=data.notes[p.id];if(!n||typeof n!=='object'||Array.isArray(n))continue;const clean={priority:n.priority===true,noOpportunity:n.noOpportunity===true,emailStatus:['sent','responded'].includes(n.emailStatus)?n.emailStatus:''};for(const k of ['diligenceNotes','researchNotes','draft','workflow','followup','outreachNotes'])if(typeof n[k]==='string')clean[k]=n[k].slice(0,100000);clean.checks={};for(const [k] of diligence)clean.checks[k]=n.checks?.[k]===true;saved[p.id]=clean;}if(persist())msg('Notes imported. Research records were not overwritten.');render();}catch(err){msg('Import failed: '+err.message);}finally{e.target.value='';}});
setupCountryFilter();
const signalCopy={'Reported process':'Partnership opportunity reported','Sponsor invitation':'Sponsor seeking partners','Watchlist':'No confirmed invitation','Procurement':'Tender / RFQ announced','Validation required':'Validation required','Sponsor claim':'Sponsor claim'};
for(const signal of [...new Set(projects.map(p=>p.signal).filter(Boolean))].sort())if(![...$('#signal').options].some(option=>option.value===signal))$('#signal').insertAdjacentHTML('beforeend',`<option>${esc(signal)}</option>`);
const signalCounts=projects.reduce((counts,p)=>{if(p.signal)counts[p.signal]=(counts[p.signal]||0)+1;return counts;},{});
for(const option of $('#signal').options){const value=option.value;const label=value?(signalCopy[value]||value):'All signals';option.value=value;option.textContent=`${label} (${value?signalCounts[value]||0:projects.length})`;}
for(const id of ['search','signal'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{sidebar();if(!current)portfolio();});
const baseRender=render;render=()=>{baseRender();clarifySignalLabels();};
function route(){const [id,t]=location.hash.slice(1).split('/');let decoded='Overview';try{decoded=decodeURIComponent(t||'Overview');}catch{}navigate(id,decoded);}
const routeProjects=route;route=()=>{const parts=location.hash.slice(1).split('/');if(parts[0]==='partners'){libraryMode='partners';current=null;partnerCurrent=partnerRecords.find(p=>p.id===parts[1])||null;partnerTab=decodeURIComponent(parts[2]||'Overview');render();return;}libraryMode='projects';partnerCurrent=null;routeProjects();};
document.addEventListener('click',e=>{const library=e.target.closest('[data-library]');if(library){switchLibrary(library.dataset.library);return;}const partnerRecord=e.target.closest('[data-partner-record]');if(partnerRecord&&libraryMode==='partners'){partnerCurrent=partnerRecords.find(p=>p.id===partnerRecord.dataset.partnerRecord)||null;partnerTab='Overview';history.replaceState(null,'',`#partners/${partnerCurrent?.id||''}/Overview`);render();return;}const partnerSection=e.target.closest('[data-partner-tab]');if(partnerSection&&libraryMode==='partners'){partnerTab=partnerSection.dataset.partnerTab;history.replaceState(null,'',`#partners/${partnerCurrent?.id||''}/${encodeURIComponent(partnerTab)}`);render();return;}if(e.target.closest('[data-partner-research]'))msg('Research route prepared; no outreach was sent.');});
window.addEventListener('hashchange',route);route();if(!storageOK)msg('Browser storage could not be read. Export your work before closing.');
contactDesk.load();partnerDesk.load();loadSendSummary();

function partnerPipelineTable(){const rows=orderedPartners(partnerMatches());return `<div class="table-wrap partner-table-wrap"><table><thead><tr><th>Partner</th><th>Country / region</th><th>Industry</th><th>Investment / JV intent</th><th>Preferred scale</th><th>Status</th><th>Latest evidence</th><th>Contacts</th><th>Review</th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="table-project-name"><button class="table-star project-star" data-partner-star="${p.id}" aria-label="${note(p).priority?'Unstar':'Star'} ${esc(p.company)}" aria-pressed="${!!note(p).priority}">${note(p).priority?'★':'☆'}</button><button class="text-button" data-partner-record="${p.id}">${esc(p.company)}</button></span><small>${esc(p.partnerType)}</small></td><td>${esc(p.country)}</td><td>${esc(p.industry)}<small>${esc(p.subSector)}</small></td><td>${esc(p.intent)}</td><td>${esc(p.scale)}</td><td>${pill(p.status)}</td><td>${esc(p.latestEvidence)}<small>${esc(p.stage)}</small></td><td>${(partnerContacts[p.id]||[]).length}</td><td><button class="quiet" data-partner-record="${p.id}" aria-label="Open ${esc(p.company)}">Open ↗</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No matching partners. Clear the sidebar search.</div>'}</div>`;}
function partnerLibraryTableView(){if(partnerCurrent){$('#breadcrumb').textContent=`${partnerCurrent.company} / ${partnerTab}`;$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">${esc(partnerCurrent.country)} · WIND PARTNER</div><h1>${esc(partnerCurrent.company)}</h1><p class="intro">${esc(partnerCurrent.partnerType)} <span class="slash">/</span> ${esc(partnerCurrent.scale)}</p><div class="summary-line"><span class="pill">${esc(partnerCurrent.status)}</span> · Latest evidence ${esc(partnerCurrent.latestEvidence)}</div></div><div class="heading-actions"><button id="export-project">Export partner</button></div></div><div class="tabs partner-tabs" role="tablist" aria-label="Partner sections">${tabs.map(t=>`<button role="tab" aria-selected="${t===partnerTab}" class="tab ${t===partnerTab?'selected':''}" data-partner-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="partner-panel" role="tabpanel">${partnerPanel()}</div>`;return;}$('#breadcrumb').textContent='Investors & JV Partners';$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">GLOBAL WIND · PARTNER RESEARCH</div><h1>Investors &amp; JV Partners</h1><p class="intro">Source-backed Asian companies with wind investment, development or JV evidence.</p></div><span class="pill">SOURCE-BACKED ONLY</span></div><div class="notice">No company is classified as actively seeking a wind investment or JV without dated evidence. Generic wind experience is not treated as current intent.</div><div class="section-head"><h2>Partner pipeline</h2><small>${partnerRecords.length} partner records · table view</small></div>${partnerPipelineTable()}<div class="tabs partner-tabs" role="tablist" aria-label="Partner sections">${tabs.map(t=>`<button role="tab" aria-selected="${t===partnerTab}" class="tab ${t===partnerTab?'selected':''}" data-partner-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="partner-panel" role="tabpanel">${partnerPanel()}</div>`;enableColumnResize($('#content table'),$('#content .section-head'),msg,'wind-partners.column-widths.v1');}
partnerLibrary=partnerLibraryTableView;
const renderPartnerLibrary=partnerLibrary;
partnerLibrary=()=>{renderPartnerLibrary();if(libraryMode==='partners'&&!partnerCurrent)configurePortfolioViewport();else if(partnerCurrent)document.body.classList.remove('portfolio-view');};
if(libraryMode==='partners'&&!partnerCurrent)render();
document.addEventListener('click',e=>{const portfolioButton=e.target.closest('#portfolio-button');if(portfolioButton&&libraryMode==='partners'){e.preventDefault();e.stopImmediatePropagation();switchLibrary('partners');}},true);
